// Behaviour test for 0x00F2A250 CScriptDef::operator= (generated by tools/mktest2.py; plain C++98, no asm).
// Function under test: the IMPLICIT member-wise assignment of the CScriptDef model below, reached through Copy exactly as in the
// row (`*this = *static_cast<const CScriptDef*>(other)`). The model's 943 members are generated from the shared header
// engine/CScriptDef.h (header order, header types) over the def base chain (CResource copy called, CDefClassBase / parent def
// assignments implicit, the sub-def map a pair vector plus the Dirty byte).
// Expected behaviour comes from RETAIL (the disassembly of 0x00F2A250, tools/map2.py): table E has one entry per copy event in
// retail order -- the member offset, the kind of copy retail makes there (a dword move, or which callee: CCharString::operator=
// 0x0099EFB0, vector<T>::operator= by element type) and the index of the member the header places at that offset.
// Checks: (1) the model's member kinds equal retail's kind at every offset and the members stand in retail's order;
// (2) the out-of-line assignments are called in retail's order on the right members (CResource first, then the sub-def map's
// vector, then 15 strings and 50 vectors), each with the matching source member; (3) afterwards all 943 members and the base
// fields equal the source; (4) strings and vectors are deep copies (changing the source afterwards does not change the copy);
// (5) operator= returns *this; (6) self-assignment makes the same 67 calls with source == destination and changes nothing (retail
// has no self test); (7) Copy through the vtable does the same as the assignment.
#include <cstdio>
#include <cstring>

enum { K_D, K_STR, K_VSTR, K_VFLOAT, K_VDEF, K_VLONG, K_VCONV, K_VFH, K_VFEAT, K_VARENA, K_VHS, K_RES, K_VPAIR };
struct SCall { int kind; const void* dst; const void* src; };
static SCall g_calls[256];
static int g_ncalls = 0;
static int g_depth = 0;
static void Record(int kind, const void* dst, const void* src)
{
    if (g_depth == 0 && g_ncalls < 256) { g_calls[g_ncalls].kind = kind; g_calls[g_ncalls].dst = dst; g_calls[g_ncalls].src = src; ++g_ncalls; }
}

class CCharString {
public:
    char* PData;
    CCharString() : PData(0) {}
    ~CCharString() { delete[] PData; }
    void Set(const char* text) { delete[] PData; PData = new char[std::strlen(text) + 1]; std::strcpy(PData, text); }
    const CCharString& operator=(const CCharString& other)
    {
        Record(K_STR, this, &other);
        if (this != &other) Set(other.PData ? other.PData : "");
        return *this;
    }
private:
    CCharString(const CCharString&);
};
