template <class T> struct VecKind;
template <> struct VecKind<CCharString> { enum { value = K_VSTR }; };
template <> struct VecKind<float> { enum { value = K_VFLOAT }; };
template <> struct VecKind<CDefString> { enum { value = K_VDEF }; };
template <> struct VecKind<long> { enum { value = K_VLONG }; };
template <> struct VecKind<CConversation> { enum { value = K_VCONV }; };
template <> struct VecKind<CFireHeartPatternDef> { enum { value = K_VFH }; };
template <> struct VecKind<CFeatDef> { enum { value = K_VFEAT }; };
