static int KindOf(const long&) { return K_D; }
static int KindOf(const float&) { return K_D; }
static int KindOf(const CDefString&) { return K_D; }
static int KindOf(const CCharString&) { return K_STR; }
template <class T> int KindOf(const vector<T>&) { return VecKind<T>::value; }

static void Fill(long& m, int seed) { m = 100000 + seed; }
static void Fill(float& m, int seed) { m = (float)seed + 0.25f; }
static void Fill(CDefString& m, int seed) { m.TablePos = 7 * seed + 3; }
static void Fill(CCharString& m, int seed) { char text[32]; std::sprintf(text, "s%d", seed); m.Set(text); }
static void Fill(CConversation& m, int seed) { m.Id = seed; }
static void Fill(CFireHeartPatternDef& m, int seed) { m.Id = seed; }
static void Fill(CFeatDef& m, int seed) { m.Id = seed; }
static void Fill(CArenaRoundDef& m, int seed) { m.Id = seed; }
static void Fill(CHeroSoulsRoundDef& m, int seed) { m.Id = seed; }
template <class T> void Fill(vector<T>& m, int seed)
{
    m.resize(1 + seed % 3);
    for (int i = 0; i < m.Count; ++i) Fill(m.Start[i], seed * 8 + i);
}

static bool Same(const long& a, const long& b) { return a == b; }
static bool Same(const float& a, const float& b) { return a == b; }
static bool Same(const CDefString& a, const CDefString& b) { return a.TablePos == b.TablePos; }
static bool Same(const CCharString& a, const CCharString& b) { return a.PData && b.PData && std::strcmp(a.PData, b.PData) == 0; }
static bool Same(const CConversation& a, const CConversation& b) { return a.Id == b.Id; }
static bool Same(const CFireHeartPatternDef& a, const CFireHeartPatternDef& b) { return a.Id == b.Id; }
static bool Same(const CFeatDef& a, const CFeatDef& b) { return a.Id == b.Id; }
static bool Same(const CArenaRoundDef& a, const CArenaRoundDef& b) { return a.Id == b.Id; }
static bool Same(const CHeroSoulsRoundDef& a, const CHeroSoulsRoundDef& b) { return a.Id == b.Id; }
template <class T> bool Same(const vector<T>& a, const vector<T>& b)
{
    if (a.Count != b.Count) return false;
    for (int i = 0; i < a.Count; ++i) if (!Same(a.Start[i], b.Start[i])) return false;
    return true;
}

// Change a class-typed member IN PLACE (same buffer): a shallow copy of it would change too.
static void Touch(long&) {}
static void Touch(float&) {}
static void Touch(CDefString&) {}
static void Touch(CCharString& m) { m.PData[0] = '#'; }
static void Touch(CConversation& m) { m.Id = -m.Id - 1; }
static void Touch(CFireHeartPatternDef& m) { m.Id = -m.Id - 1; }
static void Touch(CFeatDef& m) { m.Id = -m.Id - 1; }
static void Touch(CArenaRoundDef& m) { m.Id = -m.Id - 1; }
static void Touch(CHeroSoulsRoundDef& m) { m.Id = -m.Id - 1; }
template <class T> void Touch(vector<T>& m) { Touch(m.Start[0]); }
static void TouchElement(float& m) { m = -m - 1.0f; }
static void TouchElement(long& m) { m = -m - 1; }
static void TouchElement(CDefString& m) { m.TablePos = -m.TablePos - 1; }
static void Touch(vector<float>& m) { TouchElement(m.Start[0]); }
static void Touch(vector<long>& m) { TouchElement(m.Start[0]); }
static void Touch(vector<CDefString>& m) { TouchElement(m.Start[0]); }

struct SFill { int Seed; template <class T> void Do(int i, T& a, T&) { Fill(a, Seed + i); } };
struct SCompare { int Bad; int Count; template <class T> void Do(int i, T& a, T& b) { ++Count; if (Bad < 0 && !Same(a, b)) Bad = i; } };
struct STouch { template <class T> void Do(int, T& a, T&) { Touch(a); } };
struct SLayout {
    const void* A[943]; const void* B[943]; int Kind[943]; int Count;
    template <class T> void Do(int i, T& a, T& b) { A[i] = &a; B[i] = &b; Kind[i] = KindOf(a); ++Count; }
};

static void FillBase(CScriptDef& d, int seed)
{
    d.ResourceSize = 500 + seed;
    d.PDefManager = (void*)(&g_calls[seed % 7]);
    d.GlobalIndex = 900 + seed;
    d.Setup = (seed & 1) != 0;
    d.Template = (seed & 2) != 0;
    d.DefaultValsApplied = (seed & 4) != 0;
    d.InstantiationName.TablePos = 40 + seed;
    d.SubDefInfoMap.resize(2 + seed % 2);
    for (int i = 0; i < d.SubDefInfoMap.Count; ++i) { d.SubDefInfoMap.Start[i].first = seed + i; d.SubDefInfoMap.Start[i].second = seed * 3 + i; }
    d.SubDefInfoMap.Dirty = (seed & 1) != 0;
}
static bool SameBase(const CScriptDef& a, const CScriptDef& b)
{
    if (a.ResourceSize != b.ResourceSize || a.PDefManager != b.PDefManager || a.GlobalIndex != b.GlobalIndex) return false;
    if (a.Setup != b.Setup || a.Template != b.Template || a.DefaultValsApplied != b.DefaultValsApplied) return false;
    if (a.InstantiationName.TablePos != b.InstantiationName.TablePos || a.SubDefInfoMap.Dirty != b.SubDefInfoMap.Dirty) return false;
    if (a.SubDefInfoMap.Count != b.SubDefInfoMap.Count) return false;
    for (int i = 0; i < a.SubDefInfoMap.Count; ++i)
        if (a.SubDefInfoMap.Start[i].first != b.SubDefInfoMap.Start[i].first || a.SubDefInfoMap.Start[i].second != b.SubDefInfoMap.Start[i].second) return false;
    return true;
}
static void FillAll(CScriptDef& d, int seed) { FillBase(d, seed); SFill f; f.Seed = seed * 1000; Visit(d, d, f); }
static int FirstDifference(CScriptDef& a, CScriptDef& b)      // -1 same, -2 base differs, else the member index
{
    if (!SameBase(a, b)) return -2;
    SCompare c; c.Bad = -1; c.Count = 0; Visit(a, b, c);
    return c.Count == 943 ? c.Bad : -3;
}

static SLayout g_layout;

// The calls retail makes, in order, checked against the record of one assignment dst <- src.
static int CheckCalls(CScriptDef& dst, CScriptDef& src)
{
    g_layout.Count = 0;
    Visit(dst, src, g_layout);
    if (g_layout.Count != 943) return 1;
    int n = 0;
    if (g_ncalls < 2) return 2;
    if (g_calls[n].kind != K_RES || g_calls[n].dst != static_cast<CResource*>(&dst) || g_calls[n].src != static_cast<CResource*>(&src)) return 3;
    ++n;
    if (g_calls[n].kind != K_VPAIR || g_calls[n].dst != static_cast<vector<SPair>*>(&dst.SubDefInfoMap) || g_calls[n].src != static_cast<vector<SPair>*>(&src.SubDefInfoMap)) return 4;
    ++n;
    for (int i = 0; i < 943; ++i) {
        if (E[i].Kind == K_D) continue;
        if (n >= g_ncalls) return 5;
        if (g_calls[n].kind != E[i].Kind) return 6;
        if (g_calls[n].dst != g_layout.A[E[i].Member] || g_calls[n].src != g_layout.B[E[i].Member]) return 7;
        ++n;
    }
    if (n != g_ncalls || n != 67) return 8;
    return 0;
}

static int Run()
{
    static CScriptDef src, dst, ref, self, viaCopy;
    FillAll(src, 1); FillAll(ref, 1); FillAll(dst, 2); FillAll(self, 3); FillAll(viaCopy, 4);
    if (FirstDifference(src, ref) != -1) return 10;            // the fill is deterministic
    if (FirstDifference(src, dst) != -2) return 11;            // and the two seeds differ (base first)

    // (1) member kinds and order against retail
    g_layout.Count = 0;
    Visit(dst, src, g_layout);
    int scalars = 0;
    for (int i = 0; i < 943; ++i) {
        if (E[i].Member != i) return 12;                       // retail order == declaration order
        if (g_layout.Kind[E[i].Member] != E[i].Kind) return 13; // the member's type gives retail's kind of copy
        if (i > 0 && !(E[i - 1].Offset < E[i].Offset)) return 14;
        if (i > 0 && !((const char*)g_layout.A[E[i - 1].Member] < (const char*)g_layout.A[E[i].Member])) return 15;
        if (E[i].Kind == K_D) ++scalars;
    }
    if (scalars != 878) return 16;

    // (2) (3) (5) one assignment
    g_ncalls = 0;
    CScriptDef& result = (dst = src);
    if (&result != &dst) return 20;
    int c = CheckCalls(dst, src);
    if (c) return 20 + c;
    if (FirstDifference(dst, ref) != -1) return 30;
    if (FirstDifference(src, ref) != -1) return 31;            // the source is untouched

    // (4) deep copies: change every string / vector of the source in place
    STouch t; Visit(src, src, t);
    src.SubDefInfoMap.Start[0].second = -1;
    if (FirstDifference(src, ref) == -1) return 40;
    if (FirstDifference(dst, ref) != -1) return 41;

    // (6) self-assignment: same calls, source == destination, nothing changes
    static CScriptDef selfRef;
    FillAll(selfRef, 3);
    g_ncalls = 0;
    CScriptDef& again = (self = self);
    if (&again != &self) return 50;
    c = CheckCalls(self, self);
    if (c) return 50 + c;
    if (FirstDifference(self, selfRef) != -1) return 60;

    // (7) through the vtable, as CDefClassBase::Copy callers do
    CDefClassBase* base = &viaCopy;
    g_ncalls = 0;
    base->Copy(&ref);
    c = CheckCalls(viaCopy, ref);
    if (c) return 70 + c;
    if (FirstDifference(viaCopy, ref) != -1) return 80;
    return 0;
}

int main()
{
    int r = Run();
    if (r) { std::printf("00f2a250_TEST FAIL (%d)\n", r); return 1; }
    std::printf("00f2a250_TEST PASS\n");
    return 0;
}
